window.RumboDashboardBuilders["finland"]=(state)=>{const CFG={"tasks":[{"id":"entry","title":"Проверить основание въезда и проживания","condition":"always","tag":"До покупки билетов","body":[["Разделите въезд и переезд","Необязательные поездки граждан РФ в Финляндию и транзит через неё ограничены до дальнейшего уведомления; исключения рассматриваются по основанию поездки. Туристическая виза не является маршрутом переселения. С 1 июня 2026 года Финляндия не признаёт российские небиометрические паспорта, кроме установленных исключений и переходных случаев: до конца 2026 года есть специальные правила для ранее выданных виз и разрешений. Не стройте маршрут через российско-финскую сухопутную границу без отдельной проверки её работы у пограничной службы."]],"sources":["s0"]},{"id":"documents","title":"Подготовить документы и переводы","condition":"always","tag":"По списку выбранной процедуры","body":[["Сверьте требования ведомства","Документы не на финском, шведском или английском переводятся по правилам Migri. Для подтверждений семьи из России проверяйте требование легализации в вашей анкете: когда оно установлено, применяется апостиль. Подлинник и перевод — разные части пакета. Не заказывайте справки до проверки срока их допустимости и способа личной идентификации."]],"sources":["s3"]},{"id":"work","title":"Выбрать разрешение для работы или учёбы","condition":"always","tag":"До начала работы","body":[["Работа","Работа: выберите в Migri разрешение под вашу занятость и квалификацию; приглашение на собеседование само по себе не разрешает работать."],["Учёба","Учёба: поступление, подтверждения средств, страхования и остальные приложения по списку Migri."]],"sources":["s2"]},{"id":"family","title":"Проверить условия переезда партнёра и семьи","condition":"family","tag":"Отдельные заявления","body":[["Уточните категорию семьи","Семья: отдельное заявление члена семьи; требования к родству, возрасту и средствам зависят от статуса принимающего человека. Первое разрешение обычно оформляют до переезда; анкету и идентификацию планируйте по инструкции Enter Finland и представительства."]],"sources":["s2"]},{"id":"children","title":"Подготовить переезд ребёнка","condition":"children","tag":"До выбора жилья","body":[["Организационная рекомендация","До аренды запросите у муниципалитета порядок зачисления, языковой поддержки и помощи ребёнку с особыми образовательными или медицинскими потребностями. Соберите переводы заключений и сведения о лечении. Не обещайте автоматического признания инвалидности или немедленного доступа к выплатам: нужны проверка статуса и местная оценка."]],"sources":["s2"]},{"id":"support","title":"Согласовать необходимую ребёнку поддержку","condition":"support","tag":"Индивидуальная оценка","body":[["Индивидуальный план помощи","До выбора жилья запросите у школы, муниципалитета и клиники порядок оценки потребностей ребёнка, доступность сопровождения и продолжения терапии. Подготовьте переводы заключений, список лекарств и план помощи на переходный период. Право на конкретную услугу и её оплату подтвердите письменно."]],"sources":["s2"]},{"id":"pets","title":"Подготовить документы и маршрут питомца","condition":"pets","tag":"До бронирования перевозки","body":[["Согласуйте правила ввоза","Для собак, кошек и хорьков из России с 16 сентября 2024 года обязателен тест на антитела к бешенству в дополнение к вакцинации. Проверьте официальный подборщик по стране отправления, виду и сопровождению животного: он различает некоммерческую поездку с хозяином и импорт. Для собак отдельно требуется обработка против эхинококка; точное окно и сертификат берите из инструкции вашего маршрута."]],"sources":["s4"]},{"id":"arrival","title":"Организовать первые недели","condition":"always","tag":"После получения права на переезд","body":[["Организационная рекомендация","Подготовьте временное жильё, маршрут до него, доступные копии документов и резерв на непредвиденные расходы. Сверьте условия вашего разрешения, порядок регистрации адреса и записи в необходимые службы на официальном портале; не считайте въезд автоматическим открытием доступа ко всем услугам."]],"sources":["s2"]},{"id":"citizenship","title":"Изучить долгосрочный статус и гражданство","condition":"always","tag":"Отдельная процедура","body":[["Проверьте требования заново перед подачей","Общее требование проживания — восемь лет; при выполнении языкового требования и в некоторых других случаях возможен пятилетний период. Этого недостаточно само по себе: нужны остальные условия гражданства и правильный подсчёт отсутствий и статусов."]],"sources":["s6"]}],"profile":{"id":"finland","cabin":8,"hold":50}};function buildTasks(d){
 const conditions={always:true,family:!!d?.company&&d.company!=='solo',children:!!d&&d.children!=='none',support:!!d&&d.children!=='none'&&!!d.support?.length,pets:(!!d?.pets&&d.pets!=='none')||state.pets.length>0,remote:!!d&&['Удалённая работа','Свой бизнес'].includes(d.income)};
 const list=CFG.tasks.filter(t=>conditions[t.condition||'always']).map(t=>({...t,body:t.body.map(x=>[...x])}));
 if(!CFG.domestic&&d?.citizenship==='other')list[0].body.unshift(['Ваше гражданство','Указанные ниже условия для паспорта РФ не определяют ваш порядок въезда. Проверьте гражданство и тип паспорта по официальному источнику.']);
 return list;
}
;return {profile:CFG.profile||{},tasks:buildTasks(state.data).map(t=>({id:t.id,title:t.title,keys:t.body.map(b=>b[0])}))}};
window.RumboDashboardBuilders["iceland"]=(state)=>{const CFG={"tasks":[{"id":"entry","title":"Проверить основание въезда и проживания","condition":"always","tag":"До покупки билетов","body":[["Разделите въезд и переезд","Короткая шенгенская поездка и право жить и работать — разные процедуры. Для переезда гражданина РФ выбирайте соответствующее разрешение; порядок подачи и допустимость пребывания во время рассмотрения проверяйте по его категории. Не обещайте возможность приехать туристом и сразу начать работу."]],"sources":["s0"]},{"id":"documents","title":"Подготовить документы и переводы","condition":"always","tag":"По списку выбранной процедуры","body":[["Сверьте требования ведомства","Откройте список приложений вашей категории: паспорт, договор или поступление, подтверждение средств, страховка и другие документы. Для работы официальный список содержит особые требования к справке о несудимости и переводам. Апостиль не следует автоматически требовать от каждого документа: например, по действующей рабочей инструкции справка о несудимости обычно не нуждается в легальном удостоверении, но ведомство вправе дополнительно его запросить. Для семейных актов проверьте отдельную инструкцию."]],"sources":["s1"]},{"id":"work","title":"Выбрать разрешение для работы или учёбы","condition":"always","tag":"До начала работы","body":[["Работа","Работа: нужны работодатель, трудовой договор и соответствующие разрешения. С 8 июля 2026 года обработка заявлений на разрешения работы передана в Directorate of Immigration; старые памятки о другом ведомстве могут быть неактуальны."],["Учёба","Учёба: ориентируйтесь на действующие правила конкретной программы. Изменения июля 2026 года разрешают студентам работать в пределах 60% полной занятости без отдельного рабочего разрешения, с установленными исключениями; это не неограниченная работа."]],"sources":["s0"]},{"id":"family","title":"Проверить условия переезда партнёра и семьи","condition":"family","tag":"Отдельные заявления","body":[["Уточните категорию семьи","Семья: возможность сопровождения зависит от статуса. С июля 2026 года семейное сопровождение студентов ограничено очными программами бакалавриата, магистратуры и докторантуры; не распространяйте его автоматически на дипломные курсы."]],"sources":["s0"]},{"id":"children","title":"Подготовить переезд ребёнка","condition":"children","tag":"До выбора жилья","body":[["Организационная рекомендация","Школьную и социальную поддержку организуют муниципалитеты. При инвалидности или особенностях развития заранее обсудите школу, оценку потребностей и документы с местной службой. Иностранное заключение помогает подготовке, но не гарантирует место в конкретной специализированной школе или назначение выплаты."]],"sources":["s2"]},{"id":"support","title":"Согласовать необходимую ребёнку поддержку","condition":"support","tag":"Индивидуальная оценка","body":[["Индивидуальный план помощи","До выбора жилья запросите у школы, муниципалитета и клиники порядок оценки потребностей ребёнка, доступность сопровождения и продолжения терапии. Подготовьте переводы заключений, список лекарств и план помощи на переходный период. Право на конкретную услугу и её оплату подтвердите письменно."]],"sources":["s2"]},{"id":"pets","title":"Подготовить документы и маршрут питомца","condition":"pets","tag":"До бронирования перевозки","body":[["Согласуйте правила ввоза","Обычного европейского ветпаспорта недостаточно: необходимы разрешение MAST, обследования и двухнедельный карантин на согласованной станции. Россия отсутствует в перечне одобренных стран. На основной странице MAST предусмотрено индивидуальное разрешение для переезжающего владельца из неодобренной страны при подтверждённых проживании и уходе за животным не менее шести месяцев. Получите письменное согласование до покупки билетов; действуют ограничения пород и согласованные даты прибытия в Кефлавик."]],"sources":["s3"]},{"id":"arrival","title":"Организовать первые недели","condition":"always","tag":"После получения права на переезд","body":[["Организационная рекомендация","Подготовьте временное жильё, маршрут до него, доступные копии документов и резерв на непредвиденные расходы. Сверьте условия вашего разрешения, порядок регистрации адреса и записи в необходимые службы на официальном портале; не считайте въезд автоматическим открытием доступа ко всем услугам."]],"sources":["s0"]},{"id":"citizenship","title":"Изучить долгосрочный статус и гражданство","condition":"always","tag":"Отдельная процедура","body":[["Проверьте требования заново перед подачей","Общий ориентир — семь лет законного непрерывного проживания с выполнением остальных условий, включая постоянное разрешение либо освобождение от него, язык и финансовые требования. Есть специальные основания сокращения периода; дата в календаре не означает автоматического права на гражданство."]],"sources":["s4"]}],"profile":{"id":"iceland","cabin":8,"hold":50}};function buildTasks(d){
 const conditions={always:true,family:!!d?.company&&d.company!=='solo',children:!!d&&d.children!=='none',support:!!d&&d.children!=='none'&&!!d.support?.length,pets:(!!d?.pets&&d.pets!=='none')||state.pets.length>0,remote:!!d&&['Удалённая работа','Свой бизнес'].includes(d.income)};
 const list=CFG.tasks.filter(t=>conditions[t.condition||'always']).map(t=>({...t,body:t.body.map(x=>[...x])}));
 if(!CFG.domestic&&d?.citizenship==='other')list[0].body.unshift(['Ваше гражданство','Указанные ниже условия для паспорта РФ не определяют ваш порядок въезда. Проверьте гражданство и тип паспорта по официальному источнику.']);
 return list;
}
;return {profile:CFG.profile||{},tasks:buildTasks(state.data).map(t=>({id:t.id,title:t.title,keys:t.body.map(b=>b[0])}))}};
window.RumboDashboardBuilders["armenia"]=(state)=>{const CFG={"tasks":[{"id":"entry","title":"Проверить въезд, паспорт и транзит","body":[["Сверьте правила для граждан РФ","Гражданам РФ доступен безвизовый въезд. МИД Армении указывает общий предел безвизового пребывания 180 дней в течение года, если иной срок не установлен соглашением или законом. Перед поездкой проверьте, применяется ли это правило к вашему паспорту и цели визита."],["Проверьте весь маршрут","Проверьте срок действия паспорта, требования транзитных стран и перевозчика. Сохраните подтверждение жилья, страховку и документы о цели поездки. Правила для другого гражданства проверяются отдельно."]],"sources":["entry"],"condition":"always","tag":"Проверить заранее"},{"id":"route","title":"Выбрать основание проживания и работы","body":[["Разберите свою категорию","Гражданам стран ЕАЭС, включая РФ, разрешение на работу не требуется. Для работающего по договору с зарегистрированным в Армении работодателем предусмотрено онлайн-оформление свидетельства о законном проживании; это не универсальная программа для любого удалённого дохода."],["Получите перечень для своей процедуры","Подтвердите основания, место подачи и право работать через официальный орган. Регистрация бизнеса, аренда жилья или наличие дохода не заменяют нужного разрешения."]],"sources":["residence","work"],"condition":"always","tag":"Проверить заранее"},{"id":"documents","title":"Собрать документы и согласовать переводы","body":[["Получите персональный список","Запросите перечень по своему основанию: паспорт, договор или зачисление, семейные документы, страхование и другие подтверждения — по требованиям принимающего органа."],["Не заверяйте всё по аналогии","Проверьте применимость международных соглашений, требования к апостилю или консульской легализации и языку перевода. Уточните срок действия справок до заказа документов."]],"sources":["residence"],"condition":"always","tag":"Проверить заранее"},{"id":"remote","title":"Проверить условия удалённой работы","body":[["Проверьте свою деятельность","Гражданам стран ЕАЭС, включая РФ, разрешение на работу не требуется. Для работающего по договору с зарегистрированным в Армении работодателем предусмотрено онлайн-оформление свидетельства о законном проживании; это не универсальная программа для любого удалённого дохода."],["Отделите миграцию от налогов","Получите отдельную консультацию по налоговому резидентству, договорам и регистрации деятельности. Иностранный заказчик сам по себе не освобождает от местных обязанностей."]],"sources":["work"],"condition":"remote","tag":"Проверить заранее"},{"id":"family","title":"Согласовать документы и статус партнёра","body":[["Проверьте семейное основание","Уточните, допускает ли ваш статус воссоединение, какие отношения признаются и какие подтверждения нужны. Не считайте незарегистрированного партнёра автоматически включённым в заявление."],["Проверьте каждого члена семьи","Отдельно согласуйте право партнёра работать, страхование и сроки документов. Условия семейной подачи не следует переносить с другой страны."]],"sources":["residence"],"condition":"family","tag":"Проверить заранее"},{"id":"children","title":"Подготовить документы и обучение детей","body":[["Соберите отдельный пакет","Проверьте паспорт ребёнка, подтверждения родства и опеки, согласия по вашему маршруту. Список документов для проживания получите у миграционного органа."],["Свяжитесь со школой","До долгой аренды уточните наличие места, язык обучения, необходимые выписки и медицинские документы. Подтвердите условия зачисления письменно."]],"sources":["residence"],"condition":"children","tag":"Проверить заранее"},{"id":"support","title":"Проверить доступность и необходимую помощь","body":[["Согласуйте услуги до переезда","Запросите у конкретной клиники или школы подтверждение нужной помощи, языка общения и условий оплаты. Проверьте страховые исключения и возможность продолжения лечения."],["Оцените ежедневный маршрут","Уточните доступность входа в дом, лифта, транспорта и учебного помещения. Подготовьте переводы медицинских рекомендаций, не загружая чувствительные документы в прототип."]],"sources":["residence"],"condition":"support","tag":"Проверить заранее"},{"id":"pets","title":"Согласовать документы и перевозку питомца","body":[["Проверьте ветеринарный маршрут","Согласуйте правила перемещения из РФ с государственной ветслужбой: маршрут внутри ЕАЭС и ввоз из третьей страны регулируются по-разному. Проверьте ветеринарный паспорт, прививки и подтверждение осмотра; для других видов животных запросите отдельные условия."],["Получите подтверждение перевозчика","Согласуйте вид животного, породу, вес с переноской, её размеры и каждый рейс. Возможность перевозки и её стоимость подтвердите у перевозчика; в калькуляторе используйте свою смету."]],"sources":["pets"],"condition":"pets","tag":"Проверить заранее"},{"id":"arrival","title":"Оформить первые действия после въезда","body":[["Сверьте порядок своей категории","Проверьте применимое основание проживания и документы через миграционную службу. Для трудового основания гражданина ЕАЭС используйте соответствующую электронную процедуру, а не заявление на разрешение на работу."],["Запишите подтверждённые даты","Перенесите сроки из официальных документов в календарь. Учебные даты Rumbo помогают планировать, но не продлевают законное пребывание."]],"sources":["residence","work"],"condition":"always","tag":"Проверить заранее"},{"id":"settle","title":"Организовать первые недели","body":[["Проверьте временное жильё","Это организационный совет: начните с временного адреса, проверьте собственника, договор, коммунальные платежи и условия возврата залога до оплаты долгой аренды."],["Пройдите повседневный маршрут","Проверьте путь к работе, школе, врачу и магазину в разное время суток. Сохраните местные названия адресов и подготовьте способ общения с учреждениями."]],"sources":["tourism","safety"],"condition":"always","tag":"Проверить заранее"},{"id":"status","title":"Следить за статусом и продлением","body":[["Проверьте продление заранее","Уточните требования к сохранению основания, сроку подачи и допустимым отсутствиям у своего миграционного органа. Не считайте факт отправки заявления автоматическим продлением."],["Разделите разные процедуры","Временное проживание, постоянный статус и гражданство имеют отдельные условия. Этот план не обещает паспорт за срок проживания; для такого маршрута нужна отдельная проверка применимой категории."]],"sources":["residence"],"condition":"always","tag":"Проверить заранее"}],"profile":{"id":"armenia","quoteOnly":true,"cabin":8,"hold":50}};function buildTasks(d){
 const conditions={always:true,family:!!d?.company&&d.company!=='solo',children:!!d&&d.children!=='none',support:!!d&&d.children!=='none'&&!!d.support?.length,pets:(!!d?.pets&&d.pets!=='none')||state.pets.length>0,remote:!!d&&['Удалённая работа','Свой бизнес'].includes(d.income)};
 const list=CFG.tasks.filter(t=>conditions[t.condition||'always']).map(t=>({...t,body:t.body.map(x=>[...x])}));
 if(!CFG.domestic&&d?.citizenship==='other')list[0].body.unshift(['Ваше гражданство','Указанные ниже условия для паспорта РФ не определяют ваш порядок въезда. Проверьте гражданство и тип паспорта по официальному источнику.']);
 return list;
}
;return {profile:CFG.profile||{},tasks:buildTasks(state.data).map(t=>({id:t.id,title:t.title,keys:t.body.map(b=>b[0])}))}};
window.RumboDashboardBuilders["georgia"]=(state)=>{const CFG={"tasks":[{"id":"entry","title":"Проверить въезд, паспорт и транзит","body":[["Сверьте правила для граждан РФ","Официальная страница посольства включает РФ в список стран с безвизовым пребыванием до одного года. Это правило въезда не заменяет право на работу. С 1 января 2026 года для туристов действует требование медицинского страхования и страхования от несчастных случаев; проверьте параметры полиса перед поездкой."],["Проверьте весь маршрут","Проверьте срок действия паспорта, требования транзитных стран и перевозчика. Сохраните подтверждение жилья, страховку и документы о цели поездки. Правила для другого гражданства проверяются отдельно."]],"sources":["entry","insurance"],"condition":"always","tag":"Проверить заранее"},{"id":"route","title":"Выбрать основание проживания и работы","body":[["Разберите свою категорию","С 1 марта 2026 года для иностранцев без постоянного ВНЖ введено оформление права на трудовую деятельность, в том числе для предусмотренной правилами самостоятельной и удалённой работы. Проверьте исключения, свою категорию и связь с разрешением на проживание. Переходные условия для ранее зарегистрированных работников не применяются автоматически к новичкам."],["Получите перечень для своей процедуры","Подтвердите основания, место подачи и право работать через официальный орган. Регистрация бизнеса, аренда жилья или наличие дохода не заменяют нужного разрешения."]],"sources":["residence","work"],"condition":"always","tag":"Проверить заранее"},{"id":"documents","title":"Собрать документы и согласовать переводы","body":[["Получите персональный список","Запросите перечень по своему основанию: паспорт, договор или зачисление, семейные документы, страхование и другие подтверждения — по требованиям принимающего органа."],["Не заверяйте всё по аналогии","Проверьте применимость международных соглашений, требования к апостилю или консульской легализации и языку перевода. Уточните срок действия справок до заказа документов."]],"sources":["residence"],"condition":"always","tag":"Проверить заранее"},{"id":"remote","title":"Проверить условия удалённой работы","body":[["Проверьте свою деятельность","С 1 марта 2026 года для иностранцев без постоянного ВНЖ введено оформление права на трудовую деятельность, в том числе для предусмотренной правилами самостоятельной и удалённой работы. Проверьте исключения, свою категорию и связь с разрешением на проживание. Переходные условия для ранее зарегистрированных работников не применяются автоматически к новичкам."],["Отделите миграцию от налогов","Получите отдельную консультацию по налоговому резидентству, договорам и регистрации деятельности. Иностранный заказчик сам по себе не освобождает от местных обязанностей."]],"sources":["work"],"condition":"remote","tag":"Проверить заранее"},{"id":"family","title":"Согласовать документы и статус партнёра","body":[["Проверьте семейное основание","Уточните, допускает ли ваш статус воссоединение, какие отношения признаются и какие подтверждения нужны. Не считайте незарегистрированного партнёра автоматически включённым в заявление."],["Проверьте каждого члена семьи","Отдельно согласуйте право партнёра работать, страхование и сроки документов. Условия семейной подачи не следует переносить с другой страны."]],"sources":["residence"],"condition":"family","tag":"Проверить заранее"},{"id":"children","title":"Подготовить документы и обучение детей","body":[["Соберите отдельный пакет","Проверьте паспорт ребёнка, подтверждения родства и опеки, согласия по вашему маршруту. Список документов для проживания получите у миграционного органа."],["Свяжитесь со школой","До долгой аренды уточните наличие места, язык обучения, необходимые выписки и медицинские документы. Подтвердите условия зачисления письменно."]],"sources":["residence"],"condition":"children","tag":"Проверить заранее"},{"id":"support","title":"Проверить доступность и необходимую помощь","body":[["Согласуйте услуги до переезда","Запросите у конкретной клиники или школы подтверждение нужной помощи, языка общения и условий оплаты. Проверьте страховые исключения и возможность продолжения лечения."],["Оцените ежедневный маршрут","Уточните доступность входа в дом, лифта, транспорта и учебного помещения. Подготовьте переводы медицинских рекомендаций, не загружая чувствительные документы в прототип."]],"sources":["residence"],"condition":"support","tag":"Проверить заранее"},{"id":"pets","title":"Согласовать документы и перевозку питомца","body":[["Проверьте ветеринарный маршрут","Официальная памятка описывает ветеринарный контроль, идентификацию и вакцинацию. Необходимость анализа антител и исключения зависят от страны отправления и истории животного. Получите подтверждение для маршрута из РФ до оформления перевозки."],["Получите подтверждение перевозчика","Согласуйте вид животного, породу, вес с переноской, её размеры и каждый рейс. Возможность перевозки и её стоимость подтвердите у перевозчика; в калькуляторе используйте свою смету."]],"sources":["pets"],"condition":"pets","tag":"Проверить заранее"},{"id":"arrival","title":"Оформить первые действия после въезда","body":[["Сверьте порядок своей категории","Проверьте свою категорию через SDA и официальный портал трудовой миграции. Сохраните подтверждение въезда, страховку и документы на основание проживания; не считайте регистрацию ИП заменой миграционного оформления."],["Запишите подтверждённые даты","Перенесите сроки из официальных документов в календарь. Учебные даты Rumbo помогают планировать, но не продлевают законное пребывание."]],"sources":["residence","work"],"condition":"always","tag":"Проверить заранее"},{"id":"settle","title":"Организовать первые недели","body":[["Проверьте временное жильё","Это организационный совет: начните с временного адреса, проверьте собственника, договор, коммунальные платежи и условия возврата залога до оплаты долгой аренды."],["Пройдите повседневный маршрут","Проверьте путь к работе, школе, врачу и магазину в разное время суток. Сохраните местные названия адресов и подготовьте способ общения с учреждениями."]],"sources":["tourism","safety"],"condition":"always","tag":"Проверить заранее"},{"id":"status","title":"Следить за статусом и продлением","body":[["Проверьте продление заранее","Уточните требования к сохранению основания, сроку подачи и допустимым отсутствиям у своего миграционного органа. Не считайте факт отправки заявления автоматическим продлением."],["Разделите разные процедуры","Временное проживание, постоянный статус и гражданство имеют отдельные условия. Этот план не обещает паспорт за срок проживания; для такого маршрута нужна отдельная проверка применимой категории."]],"sources":["residence"],"condition":"always","tag":"Проверить заранее"}],"profile":{"id":"georgia","quoteOnly":true,"cabin":8,"hold":50}};function buildTasks(d){
 const conditions={always:true,family:!!d?.company&&d.company!=='solo',children:!!d&&d.children!=='none',support:!!d&&d.children!=='none'&&!!d.support?.length,pets:(!!d?.pets&&d.pets!=='none')||state.pets.length>0,remote:!!d&&['Удалённая работа','Свой бизнес'].includes(d.income)};
 const list=CFG.tasks.filter(t=>conditions[t.condition||'always']).map(t=>({...t,body:t.body.map(x=>[...x])}));
 if(!CFG.domestic&&d?.citizenship==='other')list[0].body.unshift(['Ваше гражданство','Указанные ниже условия для паспорта РФ не определяют ваш порядок въезда. Проверьте гражданство и тип паспорта по официальному источнику.']);
 return list;
}
;return {profile:CFG.profile||{},tasks:buildTasks(state.data).map(t=>({id:t.id,title:t.title,keys:t.body.map(b=>b[0])}))}};
window.RumboDashboardBuilders["kazakhstan"]=(state)=>{const CFG={"tasks":[{"id":"entry","title":"Проверить въезд, паспорт и транзит","body":[["Сверьте правила для граждан РФ","Для граждан РФ предусмотрен безвизовый въезд. Перед поездкой проверьте разрешённый срок пребывания и основание для длительного проживания: работа по договору и краткий визит — разные сценарии. На этой странице не используется устаревшая схема «30 дней без регистрации плюс продление»."],["Проверьте весь маршрут","Проверьте срок действия паспорта, требования транзитных стран и перевозчика. Сохраните подтверждение жилья, страховку и документы о цели поездки. Правила для другого гражданства проверяются отдельно."]],"sources":["entry"],"condition":"always","tag":"Проверить заранее"},{"id":"route","title":"Выбрать основание проживания и работы","body":[["Разберите свою категорию","Граждане государств ЕАЭС могут работать в Казахстане без получения разрешения на работу. Для длительного проживания оформите применимое основание и РВП; трудовой договор и освобождение от разрешения на работу не отменяют миграционных формальностей."],["Получите перечень для своей процедуры","Подтвердите основания, место подачи и право работать через официальный орган. Регистрация бизнеса, аренда жилья или наличие дохода не заменяют нужного разрешения."]],"sources":["residence","work"],"condition":"always","tag":"Проверить заранее"},{"id":"documents","title":"Собрать документы и согласовать переводы","body":[["Получите персональный список","Запросите перечень по своему основанию: паспорт, договор или зачисление, семейные документы, страхование и другие подтверждения — по требованиям принимающего органа."],["Не заверяйте всё по аналогии","Проверьте применимость международных соглашений, требования к апостилю или консульской легализации и языку перевода. Уточните срок действия справок до заказа документов."]],"sources":["residence"],"condition":"always","tag":"Проверить заранее"},{"id":"remote","title":"Проверить условия удалённой работы","body":[["Проверьте свою деятельность","Граждане государств ЕАЭС могут работать в Казахстане без получения разрешения на работу. Для длительного проживания оформите применимое основание и РВП; трудовой договор и освобождение от разрешения на работу не отменяют миграционных формальностей."],["Отделите миграцию от налогов","Получите отдельную консультацию по налоговому резидентству, договорам и регистрации деятельности. Иностранный заказчик сам по себе не освобождает от местных обязанностей."]],"sources":["work"],"condition":"remote","tag":"Проверить заранее"},{"id":"family","title":"Согласовать документы и статус партнёра","body":[["Проверьте семейное основание","Уточните, допускает ли ваш статус воссоединение, какие отношения признаются и какие подтверждения нужны. Не считайте незарегистрированного партнёра автоматически включённым в заявление."],["Проверьте каждого члена семьи","Отдельно согласуйте право партнёра работать, страхование и сроки документов. Условия семейной подачи не следует переносить с другой страны."]],"sources":["residence"],"condition":"family","tag":"Проверить заранее"},{"id":"children","title":"Подготовить документы и обучение детей","body":[["Соберите отдельный пакет","Проверьте паспорт ребёнка, подтверждения родства и опеки, согласия по вашему маршруту. Список документов для проживания получите у миграционного органа."],["Свяжитесь со школой","До долгой аренды уточните наличие места, язык обучения, необходимые выписки и медицинские документы. Подтвердите условия зачисления письменно."]],"sources":["residence"],"condition":"children","tag":"Проверить заранее"},{"id":"support","title":"Проверить доступность и необходимую помощь","body":[["Согласуйте услуги до переезда","Запросите у конкретной клиники или школы подтверждение нужной помощи, языка общения и условий оплаты. Проверьте страховые исключения и возможность продолжения лечения."],["Оцените ежедневный маршрут","Уточните доступность входа в дом, лифта, транспорта и учебного помещения. Подготовьте переводы медицинских рекомендаций, не загружая чувствительные документы в прототип."]],"sources":["residence"],"condition":"support","tag":"Проверить заранее"},{"id":"pets","title":"Согласовать документы и перевозку питомца","body":[["Проверьте ветеринарный маршрут","Уточните у государственных ветслужб правила перемещения внутри ЕАЭС, допустимый документ и отметки об осмотре и вакцинации. Не применяйте автоматически требования ввоза из третьих стран или правила коммерческой партии к личной поездке с животным."],["Получите подтверждение перевозчика","Согласуйте вид животного, породу, вес с переноской, её размеры и каждый рейс. Возможность перевозки и её стоимость подтвердите у перевозчика; в калькуляторе используйте свою смету."]],"sources":["pets"],"condition":"pets","tag":"Проверить заранее"},{"id":"arrival","title":"Оформить первые действия после въезда","body":[["Сверьте порядок своей категории","Согласуйте с принимающей стороной уведомление о прибытии и получите подтверждение. Для длительного пребывания проверьте РВП по работе, семье, учёбе или другому предусмотренному основанию на государственном портале."],["Запишите подтверждённые даты","Перенесите сроки из официальных документов в календарь. Учебные даты Rumbo помогают планировать, но не продлевают законное пребывание."]],"sources":["residence","work"],"condition":"always","tag":"Проверить заранее"},{"id":"settle","title":"Организовать первые недели","body":[["Проверьте временное жильё","Это организационный совет: начните с временного адреса, проверьте собственника, договор, коммунальные платежи и условия возврата залога до оплаты долгой аренды."],["Пройдите повседневный маршрут","Проверьте путь к работе, школе, врачу и магазину в разное время суток. Сохраните местные названия адресов и подготовьте способ общения с учреждениями."]],"sources":["tourism","safety"],"condition":"always","tag":"Проверить заранее"},{"id":"status","title":"Следить за статусом и продлением","body":[["Проверьте продление заранее","Уточните требования к сохранению основания, сроку подачи и допустимым отсутствиям у своего миграционного органа. Не считайте факт отправки заявления автоматическим продлением."],["Разделите разные процедуры","Временное проживание, постоянный статус и гражданство имеют отдельные условия. Этот план не обещает паспорт за срок проживания; для такого маршрута нужна отдельная проверка применимой категории."]],"sources":["residence"],"condition":"always","tag":"Проверить заранее"}],"profile":{"id":"kazakhstan","quoteOnly":true,"cabin":8,"hold":50}};function buildTasks(d){
 const conditions={always:true,family:!!d?.company&&d.company!=='solo',children:!!d&&d.children!=='none',support:!!d&&d.children!=='none'&&!!d.support?.length,pets:(!!d?.pets&&d.pets!=='none')||state.pets.length>0,remote:!!d&&['Удалённая работа','Свой бизнес'].includes(d.income)};
 const list=CFG.tasks.filter(t=>conditions[t.condition||'always']).map(t=>({...t,body:t.body.map(x=>[...x])}));
 if(!CFG.domestic&&d?.citizenship==='other')list[0].body.unshift(['Ваше гражданство','Указанные ниже условия для паспорта РФ не определяют ваш порядок въезда. Проверьте гражданство и тип паспорта по официальному источнику.']);
 return list;
}
;return {profile:CFG.profile||{},tasks:buildTasks(state.data).map(t=>({id:t.id,title:t.title,keys:t.body.map(b=>b[0])}))}};
window.RumboDashboardBuilders["uae"]=(state)=>{const CFG={"tasks":[{"id":"entry","title":"Проверить въезд, паспорт и транзит","body":[["Сверьте правила для граждан РФ","Соглашение с РФ предусматривает до 90 дней в течение каждого периода в 180 дней для поездок без намерения работать, учиться или проживать. Для переезда выберите отдельное основание резидентства; безвизовый визит его не заменяет."],["Проверьте весь маршрут","Проверьте срок действия паспорта, требования транзитных стран и перевозчика. Сохраните подтверждение жилья, страховку и документы о цели поездки. Правила для другого гражданства проверяются отдельно."]],"sources":["entry"],"condition":"always","tag":"Проверить заранее"},{"id":"route","title":"Выбрать основание проживания и работы","body":[["Разберите свою категорию","Работа на местного работодателя требует применимого оформления. В Дубае существует отдельная Virtual Work Residence Visa для удалённой работы на организацию за пределами ОАЭ: GDRFA указывает доход не менее 3500 USD в месяц и другие документы. Эта программа сама по себе не даёт права работать на местного работодателя."],["Получите перечень для своей процедуры","Подтвердите основания, место подачи и право работать через официальный орган. Регистрация бизнеса, аренда жилья или наличие дохода не заменяют нужного разрешения."]],"sources":["residence","work"],"condition":"always","tag":"Проверить заранее"},{"id":"documents","title":"Собрать документы и согласовать переводы","body":[["Получите персональный список","Запросите перечень по своему основанию: паспорт, договор или зачисление, семейные документы, страхование и другие подтверждения — по требованиям принимающего органа."],["Не заверяйте всё по аналогии","Проверьте применимость международных соглашений, требования к апостилю или консульской легализации и языку перевода. Уточните срок действия справок до заказа документов."]],"sources":["residence"],"condition":"always","tag":"Проверить заранее"},{"id":"remote","title":"Проверить условия удалённой работы","body":[["Проверьте свою деятельность","Работа на местного работодателя требует применимого оформления. В Дубае существует отдельная Virtual Work Residence Visa для удалённой работы на организацию за пределами ОАЭ: GDRFA указывает доход не менее 3500 USD в месяц и другие документы. Эта программа сама по себе не даёт права работать на местного работодателя."],["Отделите миграцию от налогов","Получите отдельную консультацию по налоговому резидентству, договорам и регистрации деятельности. Иностранный заказчик сам по себе не освобождает от местных обязанностей."]],"sources":["work"],"condition":"remote","tag":"Проверить заранее"},{"id":"family","title":"Согласовать документы и статус партнёра","body":[["Проверьте семейное основание","Уточните, допускает ли ваш статус воссоединение, какие отношения признаются и какие подтверждения нужны. Не считайте незарегистрированного партнёра автоматически включённым в заявление."],["Проверьте каждого члена семьи","Отдельно согласуйте право партнёра работать, страхование и сроки документов. Условия семейной подачи не следует переносить с другой страны."]],"sources":["residence"],"condition":"family","tag":"Проверить заранее"},{"id":"children","title":"Подготовить документы и обучение детей","body":[["Соберите отдельный пакет","Проверьте паспорт ребёнка, подтверждения родства и опеки, согласия по вашему маршруту. Список документов для проживания получите у миграционного органа."],["Свяжитесь со школой","До долгой аренды уточните наличие места, язык обучения, необходимые выписки и медицинские документы. Подтвердите условия зачисления письменно."]],"sources":["residence"],"condition":"children","tag":"Проверить заранее"},{"id":"support","title":"Проверить доступность и необходимую помощь","body":[["Согласуйте услуги до переезда","Запросите у конкретной клиники или школы подтверждение нужной помощи, языка общения и условий оплаты. Проверьте страховые исключения и возможность продолжения лечения."],["Оцените ежедневный маршрут","Уточните доступность входа в дом, лифта, транспорта и учебного помещения. Подготовьте переводы медицинских рекомендаций, не загружая чувствительные документы в прототип."]],"sources":["residence"],"condition":"support","tag":"Проверить заранее"},{"id":"pets","title":"Согласовать документы и перевозку питомца","body":[["Проверьте ветеринарный маршрут","До отправления оформите применимое разрешение MOCCAE. Проверьте ограничения пород, микрочип, прививки, ветеринарный сертификат и требования к анализу антител для страны отправления. Условия разрешения и авиакомпании проверяются отдельно."],["Получите подтверждение перевозчика","Согласуйте вид животного, породу, вес с переноской, её размеры и каждый рейс. Возможность перевозки и её стоимость подтвердите у перевозчика; в калькуляторе используйте свою смету."]],"sources":["pets"],"condition":"pets","tag":"Проверить заранее"},{"id":"arrival","title":"Оформить первые действия после въезда","body":[["Сверьте порядок своей категории","Согласуйте с оформляющей стороной последовательность въездного разрешения, резидентства, медицинских процедур и Emirates ID. Условия зависят от основания и эмирата; не считайте запись на услугу готовым статусом."],["Запишите подтверждённые даты","Перенесите сроки из официальных документов в календарь. Учебные даты Rumbo помогают планировать, но не продлевают законное пребывание."]],"sources":["residence","work"],"condition":"always","tag":"Проверить заранее"},{"id":"settle","title":"Организовать первые недели","body":[["Проверьте временное жильё","Это организационный совет: начните с временного адреса, проверьте собственника, договор, коммунальные платежи и условия возврата залога до оплаты долгой аренды."],["Пройдите повседневный маршрут","Проверьте путь к работе, школе, врачу и магазину в разное время суток. Сохраните местные названия адресов и подготовьте способ общения с учреждениями."]],"sources":["tourism","safety"],"condition":"always","tag":"Проверить заранее"},{"id":"status","title":"Следить за статусом и продлением","body":[["Проверьте продление заранее","Уточните требования к сохранению основания, сроку подачи и допустимым отсутствиям у своего миграционного органа. Не считайте факт отправки заявления автоматическим продлением."],["Разделите разные процедуры","Временное проживание, постоянный статус и гражданство имеют отдельные условия. Этот план не обещает паспорт за срок проживания; для такого маршрута нужна отдельная проверка применимой категории."]],"sources":["residence"],"condition":"always","tag":"Проверить заранее"}],"profile":{"id":"uae","quoteOnly":true,"cabin":8,"hold":50}};function buildTasks(d){
 const conditions={always:true,family:!!d?.company&&d.company!=='solo',children:!!d&&d.children!=='none',support:!!d&&d.children!=='none'&&!!d.support?.length,pets:(!!d?.pets&&d.pets!=='none')||state.pets.length>0,remote:!!d&&['Удалённая работа','Свой бизнес'].includes(d.income)};
 const list=CFG.tasks.filter(t=>conditions[t.condition||'always']).map(t=>({...t,body:t.body.map(x=>[...x])}));
 if(!CFG.domestic&&d?.citizenship==='other')list[0].body.unshift(['Ваше гражданство','Указанные ниже условия для паспорта РФ не определяют ваш порядок въезда. Проверьте гражданство и тип паспорта по официальному источнику.']);
 return list;
}
;return {profile:CFG.profile||{},tasks:buildTasks(state.data).map(t=>({id:t.id,title:t.title,keys:t.body.map(b=>b[0])}))}};
window.RumboDashboardBuilders["oman"]=(state)=>{const CFG={"tasks":[{"id":"entry","title":"Проверить въезд, паспорт и транзит","body":[["Сверьте правила для граждан РФ","По соглашению РФ и Омана, действующему с 18 июля 2025 года, краткие безвизовые поездки допускаются до 30 дней за визит и до 90 дней за календарный год. Для работы, учёбы и проживания требуется соответствующее оформление. Общее правило 14 дней для части туристов нельзя подставлять вместо соглашения для россиян."],["Проверьте весь маршрут","Проверьте срок действия паспорта, требования транзитных стран и перевозчика. Сохраните подтверждение жилья, страховку и документы о цели поездки. Правила для другого гражданства проверяются отдельно."]],"sources":["entry"],"condition":"always","tag":"Проверить заранее"},{"id":"route","title":"Выбрать основание проживания и работы","body":[["Разберите свою категорию","Рабочая виза оформляется по заявке и под ответственность работодателя при выполнении требований государственных органов. Согласуйте должность, документы и разрешение до начала работы. Туристический въезд и зарубежный доход сами по себе не дают права на местную работу."],["Получите перечень для своей процедуры","Подтвердите основания, место подачи и право работать через официальный орган. Регистрация бизнеса, аренда жилья или наличие дохода не заменяют нужного разрешения."]],"sources":["residence","work"],"condition":"always","tag":"Проверить заранее"},{"id":"documents","title":"Собрать документы и согласовать переводы","body":[["Получите персональный список","Запросите перечень по своему основанию: паспорт, договор или зачисление, семейные документы, страхование и другие подтверждения — по требованиям принимающего органа."],["Не заверяйте всё по аналогии","Проверьте применимость международных соглашений, требования к апостилю или консульской легализации и языку перевода. Уточните срок действия справок до заказа документов."]],"sources":["residence"],"condition":"always","tag":"Проверить заранее"},{"id":"remote","title":"Проверить условия удалённой работы","body":[["Проверьте свою деятельность","Рабочая виза оформляется по заявке и под ответственность работодателя при выполнении требований государственных органов. Согласуйте должность, документы и разрешение до начала работы. Туристический въезд и зарубежный доход сами по себе не дают права на местную работу."],["Отделите миграцию от налогов","Получите отдельную консультацию по налоговому резидентству, договорам и регистрации деятельности. Иностранный заказчик сам по себе не освобождает от местных обязанностей."]],"sources":["work"],"condition":"remote","tag":"Проверить заранее"},{"id":"family","title":"Согласовать документы и статус партнёра","body":[["Проверьте семейное основание","Уточните, допускает ли ваш статус воссоединение, какие отношения признаются и какие подтверждения нужны. Не считайте незарегистрированного партнёра автоматически включённым в заявление."],["Проверьте каждого члена семьи","Отдельно согласуйте право партнёра работать, страхование и сроки документов. Условия семейной подачи не следует переносить с другой страны."]],"sources":["residence"],"condition":"family","tag":"Проверить заранее"},{"id":"children","title":"Подготовить документы и обучение детей","body":[["Соберите отдельный пакет","Проверьте паспорт ребёнка, подтверждения родства и опеки, согласия по вашему маршруту. Список документов для проживания получите у миграционного органа."],["Свяжитесь со школой","До долгой аренды уточните наличие места, язык обучения, необходимые выписки и медицинские документы. Подтвердите условия зачисления письменно."]],"sources":["residence"],"condition":"children","tag":"Проверить заранее"},{"id":"support","title":"Проверить доступность и необходимую помощь","body":[["Согласуйте услуги до переезда","Запросите у конкретной клиники или школы подтверждение нужной помощи, языка общения и условий оплаты. Проверьте страховые исключения и возможность продолжения лечения."],["Оцените ежедневный маршрут","Уточните доступность входа в дом, лифта, транспорта и учебного помещения. Подготовьте переводы медицинских рекомендаций, не загружая чувствительные документы в прототип."]],"sources":["residence"],"condition":"support","tag":"Проверить заранее"},{"id":"pets","title":"Согласовать документы и перевозку питомца","body":[["Проверьте ветеринарный маршрут","Для собак и кошек предусмотрено предварительное ветеринарное разрешение на ввоз. Проверьте условия разрешения, идентификацию, вакцинацию и документы с ветслужбой; отдельно подтвердите возможность перевозки на каждом рейсе."],["Получите подтверждение перевозчика","Согласуйте вид животного, породу, вес с переноской, её размеры и каждый рейс. Возможность перевозки и её стоимость подтвердите у перевозчика; в калькуляторе используйте свою смету."]],"sources":["pets"],"condition":"pets","tag":"Проверить заранее"},{"id":"arrival","title":"Оформить первые действия после въезда","body":[["Сверьте порядок своей категории","Проверьте у работодателя или оформляющей стороны этапы визы и резидентских документов. Сохраните подтверждения подачи и фактические сроки; не начинайте деятельность только на основании обещания оформить документы позже."],["Запишите подтверждённые даты","Перенесите сроки из официальных документов в календарь. Учебные даты Rumbo помогают планировать, но не продлевают законное пребывание."]],"sources":["residence","work"],"condition":"always","tag":"Проверить заранее"},{"id":"settle","title":"Организовать первые недели","body":[["Проверьте временное жильё","Это организационный совет: начните с временного адреса, проверьте собственника, договор, коммунальные платежи и условия возврата залога до оплаты долгой аренды."],["Пройдите повседневный маршрут","Проверьте путь к работе, школе, врачу и магазину в разное время суток. Сохраните местные названия адресов и подготовьте способ общения с учреждениями."]],"sources":["tourism","safety"],"condition":"always","tag":"Проверить заранее"},{"id":"status","title":"Следить за статусом и продлением","body":[["Проверьте продление заранее","Уточните требования к сохранению основания, сроку подачи и допустимым отсутствиям у своего миграционного органа. Не считайте факт отправки заявления автоматическим продлением."],["Разделите разные процедуры","Временное проживание, постоянный статус и гражданство имеют отдельные условия. Этот план не обещает паспорт за срок проживания; для такого маршрута нужна отдельная проверка применимой категории."]],"sources":["residence"],"condition":"always","tag":"Проверить заранее"}],"profile":{"id":"oman","quoteOnly":true,"cabin":8,"hold":50}};function buildTasks(d){
 const conditions={always:true,family:!!d?.company&&d.company!=='solo',children:!!d&&d.children!=='none',support:!!d&&d.children!=='none'&&!!d.support?.length,pets:(!!d?.pets&&d.pets!=='none')||state.pets.length>0,remote:!!d&&['Удалённая работа','Свой бизнес'].includes(d.income)};
 const list=CFG.tasks.filter(t=>conditions[t.condition||'always']).map(t=>({...t,body:t.body.map(x=>[...x])}));
 if(!CFG.domestic&&d?.citizenship==='other')list[0].body.unshift(['Ваше гражданство','Указанные ниже условия для паспорта РФ не определяют ваш порядок въезда. Проверьте гражданство и тип паспорта по официальному источнику.']);
 return list;
}
;return {profile:CFG.profile||{},tasks:buildTasks(state.data).map(t=>({id:t.id,title:t.title,keys:t.body.map(b=>b[0])}))}};
window.RumboDashboardBuilders["qatar"]=(state)=>{const CFG={"tasks":[{"id":"entry","title":"Проверить въезд, паспорт и транзит","body":[["Сверьте правила для граждан РФ","Соглашение с РФ предусматривает до 90 дней в течение каждого периода в 180 дней для поездок без намерения работать, учиться или проживать. МИД РФ также указывает требование медицинской страховки на период пребывания. Проверьте паспорт и параметры полиса перед вылетом."],["Проверьте весь маршрут","Проверьте срок действия паспорта, требования транзитных стран и перевозчика. Сохраните подтверждение жилья, страховку и документы о цели поездки. Правила для другого гражданства проверяются отдельно."]],"sources":["entry"],"condition":"always","tag":"Проверить заранее"},{"id":"route","title":"Выбрать основание проживания и работы","body":[["Разберите свою категорию","Для работы и проживания обычно требуется оформление через работодателя и МВД Катара. Проверьте применимую категорию, договор и последовательность получения разрешений. Краткая поездка, гостевая виза и разрешение на работу — разные документы."],["Получите перечень для своей процедуры","Подтвердите основания, место подачи и право работать через официальный орган. Регистрация бизнеса, аренда жилья или наличие дохода не заменяют нужного разрешения."]],"sources":["residence","work"],"condition":"always","tag":"Проверить заранее"},{"id":"documents","title":"Собрать документы и согласовать переводы","body":[["Получите персональный список","Запросите перечень по своему основанию: паспорт, договор или зачисление, семейные документы, страхование и другие подтверждения — по требованиям принимающего органа."],["Не заверяйте всё по аналогии","Проверьте применимость международных соглашений, требования к апостилю или консульской легализации и языку перевода. Уточните срок действия справок до заказа документов."]],"sources":["residence"],"condition":"always","tag":"Проверить заранее"},{"id":"remote","title":"Проверить условия удалённой работы","body":[["Проверьте свою деятельность","Для работы и проживания обычно требуется оформление через работодателя и МВД Катара. Проверьте применимую категорию, договор и последовательность получения разрешений. Краткая поездка, гостевая виза и разрешение на работу — разные документы."],["Отделите миграцию от налогов","Получите отдельную консультацию по налоговому резидентству, договорам и регистрации деятельности. Иностранный заказчик сам по себе не освобождает от местных обязанностей."]],"sources":["work"],"condition":"remote","tag":"Проверить заранее"},{"id":"family","title":"Согласовать документы и статус партнёра","body":[["Проверьте семейное основание","Уточните, допускает ли ваш статус воссоединение, какие отношения признаются и какие подтверждения нужны. Не считайте незарегистрированного партнёра автоматически включённым в заявление."],["Проверьте каждого члена семьи","Отдельно согласуйте право партнёра работать, страхование и сроки документов. Условия семейной подачи не следует переносить с другой страны."]],"sources":["residence"],"condition":"family","tag":"Проверить заранее"},{"id":"children","title":"Подготовить документы и обучение детей","body":[["Соберите отдельный пакет","Проверьте паспорт ребёнка, подтверждения родства и опеки, согласия по вашему маршруту. Список документов для проживания получите у миграционного органа."],["Свяжитесь со школой","До долгой аренды уточните наличие места, язык обучения, необходимые выписки и медицинские документы. Подтвердите условия зачисления письменно."]],"sources":["residence"],"condition":"children","tag":"Проверить заранее"},{"id":"support","title":"Проверить доступность и необходимую помощь","body":[["Согласуйте услуги до переезда","Запросите у конкретной клиники или школы подтверждение нужной помощи, языка общения и условий оплаты. Проверьте страховые исключения и возможность продолжения лечения."],["Оцените ежедневный маршрут","Уточните доступность входа в дом, лифта, транспорта и учебного помещения. Подготовьте переводы медицинских рекомендаций, не загружая чувствительные документы в прототип."]],"sources":["residence"],"condition":"support","tag":"Проверить заранее"},{"id":"pets","title":"Согласовать документы и перевозку питомца","body":[["Проверьте ветеринарный маршрут","Для ввоза собак и кошек согласуйте предварительное разрешение с ветеринарным подразделением Министерства муниципалитета. Уточните срок разрешения, прививки и ограничения пород для своей категории. Проверьте также возможность проживания с животным и правила доступа к местам прогулок."],["Получите подтверждение перевозчика","Согласуйте вид животного, породу, вес с переноской, её размеры и каждый рейс. Возможность перевозки и её стоимость подтвердите у перевозчика; в калькуляторе используйте свою смету."]],"sources":["pets"],"condition":"pets","tag":"Проверить заранее"},{"id":"arrival","title":"Оформить первые действия после въезда","body":[["Сверьте порядок своей категории","Согласуйте с работодателем или принимающей стороной оформление разрешения на проживание и Qatar ID, необходимые медицинские проверки и другие действия своей категории. Сохраните документы и подтверждённые сроки."],["Запишите подтверждённые даты","Перенесите сроки из официальных документов в календарь. Учебные даты Rumbo помогают планировать, но не продлевают законное пребывание."]],"sources":["residence","work"],"condition":"always","tag":"Проверить заранее"},{"id":"settle","title":"Организовать первые недели","body":[["Проверьте временное жильё","Это организационный совет: начните с временного адреса, проверьте собственника, договор, коммунальные платежи и условия возврата залога до оплаты долгой аренды."],["Пройдите повседневный маршрут","Проверьте путь к работе, школе, врачу и магазину в разное время суток. Сохраните местные названия адресов и подготовьте способ общения с учреждениями."]],"sources":["tourism","safety"],"condition":"always","tag":"Проверить заранее"},{"id":"status","title":"Следить за статусом и продлением","body":[["Проверьте продление заранее","Уточните требования к сохранению основания, сроку подачи и допустимым отсутствиям у своего миграционного органа. Не считайте факт отправки заявления автоматическим продлением."],["Разделите разные процедуры","Временное проживание, постоянный статус и гражданство имеют отдельные условия. Этот план не обещает паспорт за срок проживания; для такого маршрута нужна отдельная проверка применимой категории."]],"sources":["residence"],"condition":"always","tag":"Проверить заранее"}],"profile":{"id":"qatar","quoteOnly":true,"cabin":8,"hold":50}};function buildTasks(d){
 const conditions={always:true,family:!!d?.company&&d.company!=='solo',children:!!d&&d.children!=='none',support:!!d&&d.children!=='none'&&!!d.support?.length,pets:(!!d?.pets&&d.pets!=='none')||state.pets.length>0,remote:!!d&&['Удалённая работа','Свой бизнес'].includes(d.income)};
 const list=CFG.tasks.filter(t=>conditions[t.condition||'always']).map(t=>({...t,body:t.body.map(x=>[...x])}));
 if(!CFG.domestic&&d?.citizenship==='other')list[0].body.unshift(['Ваше гражданство','Указанные ниже условия для паспорта РФ не определяют ваш порядок въезда. Проверьте гражданство и тип паспорта по официальному источнику.']);
 return list;
}
;return {profile:CFG.profile||{},tasks:buildTasks(state.data).map(t=>({id:t.id,title:t.title,keys:t.body.map(b=>b[0])}))}};
